        if current == goal:
            return path + [current]

        row, col = current

        neighbors = [(row - 1, col), (row + 1, col), (row, col - 1), (row, col + 1)]

        for neighbor_row, neighbor_col in neighbors:
            if is_valid(neighbor_row, neighbor_col) and (neighbor_row, neighbor_col) not in path:
